"""Mira - Specialist Agent (Planner / Risk Assessor / Status Reporter / Milestone Tracker /
Stakeholder Comms / Clarification). One component, many instances: each node on the canvas holds
its own role prompt.

After generation, a deterministic grounding validator checks the answer against the Project
Knowledge Base (unknown task/risk IDs, out-of-sprint tasks, numeric targets not in the description,
wrong status counts) and appends a visible verdict. The verdict is also logged to the trace.

Self-contained so it can be pasted into a Langflow "Custom Component" node.
"""

from __future__ import annotations

import json
import re

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, HandleInput, MessageInput, MultilineInput, Output, StrInput
from lfx.schema.message import Message

GLOBAL_RULES = """GROUNDING RULES (apply to every answer):
1. Use ONLY facts in the CONTEXT PACKET. Never invent tasks, task IDs, owners, dates, risks, milestones,
   goals, budgets, percentages or progress numbers.
2. Copy pre-computed counts and dates exactly. Do not recount or re-derive them.
3. Cite sources inline: task IDs (e.g. T024), risk IDs (e.g. R05), phase numbers, file names.
4. If something the user asked for is not in the packet, say "Not available in the provided data" and
   state what input would be needed - do not fill the gap with assumptions.
5. Anything you recommend that is not in the data must be labelled "Recommendation" or "Assumption".
6. Output clean Markdown, ready to paste into a doc or email. Be concise and specific."""


def _header(packet: str) -> dict:
    m = re.search(r"<!--MIRA (\{.*?\})-->", packet or "")
    try:
        return json.loads(m.group(1)) if m else {}
    except json.JSONDecodeError:
        return {}


def grounding_check(answer: str, packet: str, facts: dict) -> list[str]:
    """Deterministic post-generation checks. Returns a list of issues (empty = pass)."""
    issues: list[str] = []
    if not facts:
        return issues
    hdr = _header(packet)
    route = hdr.get("route")
    task_ids = set(facts.get("task_ids", []))
    risk_ids = set(facts.get("risk_ids", []))
    tasks = {t["task_id"]: t for t in facts.get("tasks", [])}

    cited_tasks = set(re.findall(r"\bT\d{3}\b", answer))
    cited_risks = set(re.findall(r"\bR\d{2}\b", answer))
    if unknown := sorted(cited_tasks - task_ids):
        issues.append(f"Unknown task IDs cited (not on task board): {', '.join(unknown)}")
    if unknown := sorted(cited_risks - risk_ids):
        issues.append(f"Unknown risk IDs cited (not in risk register): {', '.join(unknown)}")

    if route == "stakeholder" and hdr.get("sprint"):
        sp = hdr["sprint"]
        leaked = sorted(i for i in cited_tasks if tasks.get(i, {}).get("sprint_num") != sp)
        leaked += sorted(t["task_id"] for t in tasks.values() if t.get("sprint_num") != sp
                         and t["task_name"].lower() in answer.lower() and t["task_id"] not in leaked)
        if leaked:
            issues.append(f"Mentions tasks outside Sprint {sp}: {', '.join(sorted(set(leaked)))}")

    if route == "planner":
        allowed = {p.replace(" ", "") for p in facts.get("stated_numeric_targets", [])}
        used = {p.replace(" ", "") for p in re.findall(r"\b\d+(?:\.\d+)?\s?%", answer)}
        if extra := sorted(used - allowed):
            issues.append(f"Percentages not in the project description: {', '.join(extra)}")

    if route == "status" and not hdr.get("sprint"):
        counts = facts.get("status_counts", {})
        for label, key in [("done", "Done"), ("in progress", "In Progress"), ("blocked", "Blocked"),
                           ("to do", "To Do")]:
            for m in re.finditer(rf"\b{label}\b[\"*\s:|=\-–]{{0,8}}(\d+)\b", answer, re.I):
                if int(m.group(1)) != counts.get(key):
                    issues.append(f"Count for '{key}' shown as {m.group(1)}, data says {counts.get(key)}")
                    break

    if route == "tracker":
        req = re.search(r"## USER REQUEST\n(.*?)\n\n", packet, re.S)
        if req and "blocked" in req.group(1).lower():
            for t in facts.get("blocked_tasks", []):
                if t["task_id"] not in answer:
                    issues.append(f"Blocked task {t['task_id']} not mentioned")
    return issues


def dry_run_answer(agent_name: str, packet: str) -> str:
    """Used when no LLM is connected: shows exactly what the agent would be grounded on."""
    body = re.sub(r"<!--MIRA .*?-->\n*", "", packet, flags=re.S)
    return f"### {agent_name} — DRY RUN (no LLM connected)\nGrounded context the agent would use:\n\n{body}"


class MiraSpecialistAgent(Component):
    display_name = "Mira · Specialist Agent"
    description = "Role-prompted LLM agent that answers only from the grounded context packet, then self-validates."
    icon = "bot"
    name = "MiraSpecialistAgent"

    inputs = [
        StrInput(name="agent_name", display_name="Agent Name", value="Specialist Agent"),
        MultilineInput(name="role_prompt", display_name="Role Prompt (system)",
                       info="Role, method and output format for this specialist."),
        MessageInput(name="context_packet", display_name="Context Packet", required=True,
                     info="Connect from the Orchestrator output for this agent."),
        HandleInput(name="llm", display_name="LLM", input_types=["LanguageModel"], required=False),
        DataInput(name="knowledge_base", display_name="Project Facts (for validation)", required=False),
    ]

    outputs = [Output(display_name="Answer", name="answer", method="run_agent")]

    def run_agent(self) -> Message:
        packet = self.context_packet.text if isinstance(self.context_packet, Message) else str(self.context_packet)
        facts = self.knowledge_base.data if self.knowledge_base else {}
        if not packet.strip():
            self.stop("answer")
            return Message(text="")

        if self.llm is None:
            answer = dry_run_answer(self.agent_name, packet)
        else:
            from langchain_core.messages import HumanMessage, SystemMessage

            messages = [
                SystemMessage(content=f"You are Mira's {self.agent_name}.\n\n{self.role_prompt}\n\n{GLOBAL_RULES}"),
                HumanMessage(content=f"CONTEXT PACKET\n=============\n{packet}\n\nWrite the response now."),
            ]
            resp = self.llm.invoke(messages, config={"callbacks": self.get_langchain_callbacks(),
                                                     "run_name": f"mira_{self.agent_name.lower().replace(' ', '_')}"})
            answer = getattr(resp, "content", str(resp))
            if isinstance(answer, list):  # some providers return content blocks
                answer = "".join(b.get("text", "") if isinstance(b, dict) else str(b) for b in answer)

        issues = grounding_check(answer, packet, facts)
        if facts:
            if issues:
                answer += "\n\n---\n**⚠ Mira grounding check — review before sharing:**\n" + "\n".join(
                    f"- {i}" for i in issues)
            else:
                answer += (f"\n\n---\n_Grounding check passed · Source data as of {facts.get('as_of_date')} · "
                           f"{self.agent_name}_")
        self.status = {"agent": self.agent_name, "grounding_issues": issues}
        self.log({"grounding_issues": issues, "agent": self.agent_name}, name="grounding_check")
        return Message(text=answer, sender="Machine", sender_name=f"Mira · {self.agent_name}")

